import{_ as n,c as i,o as s,a2 as a}from"./chunks/framework.PGES7OoM.js";const p=JSON.parse('{"title":"setCurvyConfig","description":"Replaces or clears the ambient Curvy config.","frontmatter":{"title":"setCurvyConfig","description":"Replaces or clears the ambient Curvy config.","rawMarkdown":"---\\ntitle: setCurvyConfig\\ndescription: Replaces or clears the ambient Curvy config.\\n---\\n\\n# setCurvyConfig\\n\\nSets the [ambient config](/sdk/config/#ambient-config) used by actions that do not receive an explicit `config`.\\n\\n## Import\\n\\n```ts\\nimport { setCurvyConfig } from \\"@0xcurvy/curvy-sdk/config\\";\\n```\\n\\n## Usage\\n\\n```ts\\nsetCurvyConfig(config);\\n```\\n\\nPassing `null` clears the ambient reference:\\n\\n```ts\\nsetCurvyConfig(null);\\n```\\n\\n::: warning Lifecycle\\nReplacing or clearing the ambient reference does not destroy the previous config. Call [`destroyConfig`](/sdk/config/destroyConfig) first when that config is no longer needed.\\n:::\\n\\n## Returns\\n\\n`void`\\n\\n## Parameters\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig | null`\\n- **Required:** yes\\n\\nThe config to register, or `null` to clear the current ambient value.\\n\\n```ts\\nsetCurvyConfig(\\n  config, // [!code focus]\\n);\\n```\\n\\n## Related\\n\\n- [`getCurvyConfig`](/sdk/config/getCurvyConfig)\\n- [`peekCurvyConfig`](/sdk/config/peekCurvyConfig)\\n- [`destroyConfig`](/sdk/config/destroyConfig)\\n","rawMarkdownPath":"/_raw/sdk/config/setCurvyConfig.md","rawMarkdownTitle":"setCurvyConfig","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/config/setCurvyConfig.md"},"headers":[],"relativePath":"sdk/config/setCurvyConfig.md","filePath":"sdk/config/setCurvyConfig.md","lastUpdated":1786521734000}'),t={name:"sdk/config/setCurvyConfig.md"};function o(r,e,l,c,d,g){return s(),i("div",null,[...e[0]||(e[0]=[a("",18)])])}const u=n(t,[["render",o]]);export{p as __pageData,u as default};
